package com.surakshasetu;
import android.app.*; import android.content.*; import android.os.*;
public final class Alert { public static void show(Context c,String title,String text){ c.getSharedPreferences("pulse",Context.MODE_PRIVATE).edit().putInt("incidents",c.getSharedPreferences("pulse",Context.MODE_PRIVATE).getInt("incidents",0)+1).apply(); NotificationManager n=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE); String ch="alerts"; if(Build.VERSION.SDK_INT>=26)n.createNotificationChannel(new NotificationChannel(ch,"Safety alerts",NotificationManager.IMPORTANCE_HIGH)); n.notify((int)(System.currentTimeMillis()%100000),new Notification.Builder(c,ch).setSmallIcon(R.drawable.ic_launcher).setContentTitle(title).setContentText(text).setStyle(new Notification.BigTextStyle().bigText(text)).setAutoCancel(true).build()); } }
